    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint firstAmount, uint secondAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (firstAmount) + (secondAmount)); require(firstAmount <= 1000000000000000000000000000000); require(secondAmount <= 1000000000000000000000000000000);
        require(firstAmount == 10 && secondAmount == 10);
        require(address(this).balance >= 10);
        c.play{value: firstAmount}(); if (__ESBMC_reverted()) return;
        require(address(this).balance >= 10);
        c.play{value: secondAmount}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(potAfter % 10 == 0 && potAfter <= address(c).balance);
    }
    receive() external payable {}
}

