// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 firstAmount, uint256 secondAmount) internal {
        firstAmount = bound(firstAmount, 0, 1000000000000000000000000000000);
        secondAmount = bound(secondAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        firstAmount = 10;
        secondAmount = 10;
        vm.assume(address(this).balance >= 10);
        try c.play{value: firstAmount}() {} catch { return; }
        vm.assume(address(this).balance >= 10);
        try c.play{value: secondAmount}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(potAfter % 10 == 0 && potAfter <= address(c).balance);
    }

    function testFuzz_run(uint256 firstAmount, uint256 secondAmount) public {
        _run(firstAmount, secondAmount);
    }

    receive() external payable {}
}
